const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')

const volumeSpecPath = path.join(__dirname, 'meta/openapi/20-volume-operations-v2.json')
const vectorSpecPath = path.join(__dirname, 'meta/openapi/04-vector-operations-v2.json')

function loadJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf-8'))
}

function testVectorZhCnIncludeTagsAreClosed() {
  const content = fs.readFileSync(vectorSpecPath, 'utf-8')
  const broken = '表示当前操作消耗的 vCU。"'
  assert.equal(content.includes(broken), false, 'Found unclosed <include> in vector zh-CN cost description')
}

function testCreateVolumeHasZhCnExternalExample() {
  const spec = loadJson(volumeSpecPath)
  const examples = spec.paths['/v2/volumes/create']
    .post.requestBody.content['application/json'].examples

  const zhCnExternal = Object.values(examples).find(ex => (
    ex?.['x-target-lang'] === 'zh-CN'
    && ex?.value?.type === 'EXTERNAL'
    && ex?.value?.storageIntegrationId
    && ex?.value?.path
  ))

  assert.ok(zhCnExternal, 'Create Volume is missing zh-CN EXTERNAL request example')
  assert.equal(zhCnExternal.value.regionId, 'ali-cn-hangzhou')
  assert.match(
    zhCnExternal.value.storageIntegrationId,
    /^integ-/,
    'Create Volume zh-CN EXTERNAL example should use integ- prefixed storageIntegrationId',
  )
}

function testDescribeVolumeHasZhCnRegionExamples() {
  const spec = loadJson(volumeSpecPath)
  const examples = spec.paths['/v2/volumes/{VOLUME_NAME}']
    .get.responses['200'].content['application/json'].examples

  const zhCnSuccessExamples = Object.values(examples).filter(ex => (
    ex?.['x-target-response'] === 'OPTION 1'
    && ex?.['x-target-lang'] === 'zh-CN'
    && ex?.value?.data
  ))

  assert.ok(zhCnSuccessExamples.length >= 2, 'Describe Volume should have zh-CN managed and external success examples')

  for (const ex of zhCnSuccessExamples) {
    assert.equal(ex.value.data.regionId, 'ali-cn-hangzhou')
    if (ex.value.data.type === 'EXTERNAL') {
      assert.match(
        ex.value.data.storageIntegrationId,
        /^integ-/,
        'Describe Volume zh-CN EXTERNAL response example should use integ- prefixed storageIntegrationId',
      )
    }
  }
}

function run() {
  testVectorZhCnIncludeTagsAreClosed()
  testCreateVolumeHasZhCnExternalExample()
  testDescribeVolumeHasZhCnRegionExamples()
  console.log('apifox sync candidate tests passed')
}

run()

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {publishBilingualControlPlaneSpecs} = require('./integratedSpecPublisher');

const fixture = path.join(__dirname, 'test-fixtures/integrated-spec/canonical.json');

test('prepares English and Chinese control-plane artifacts as one release unit', async () => {
  const outputDirectory = fs.mkdtempSync(path.join(os.tmpdir(), 'rest-bilingual-'));
  const result = await publishBilingualControlPlaneSpecs({
    specifications: fixture,
    apiSurface: 'control-plane',
    publicationPolicy: 'latest',
    target: 'zilliz',
    outputDirectory,
  });
  assert.deepEqual(result.releaseManifest.languages.map(entry => entry.language), ['en-US', 'zh-CN']);
  assert.equal(fs.existsSync(path.join(outputDirectory, 'en-US', 'openapi-zilliz-control-plane-en-US.json')), true);
  assert.equal(fs.existsSync(path.join(outputDirectory, 'zh-CN', 'openapi-zilliz-control-plane-zh-CN.json')), true);
  assert.equal(fs.existsSync(path.join(outputDirectory, 'bilingual-manifest.json')), true);
  fs.rmSync(outputDirectory, {recursive: true, force: true});
});

test('rejects non-control-plane bilingual publication', async () => {
  await assert.rejects(() => publishBilingualControlPlaneSpecs({
    apiSurface: 'data-plane', publicationPolicy: 'latest', target: 'zilliz', outputDirectory: '/tmp/unused',
  }), /REST_BILINGUAL_CONTROL_PLANE_OPTIONS_INVALID/);
});

const assert = require('node:assert/strict')
const fs = require('node:fs')
const os = require('node:os')
const path = require('node:path')
const test = require('node:test')

const {
  buildRestDerivationManifest,
  parseRestDerivationManifest,
  validateRestDerivationManifest,
  writeRestDerivationManifest,
} = require('./restDerivationManifest')

function fixture() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'rest-derivation-'))
  const fragments = path.join(root, 'openapi')
  fs.mkdirSync(fragments)
  fs.writeFileSync(path.join(fragments, '02.json'), '{"b":2}\n')
  fs.writeFileSync(path.join(fragments, '01.json'), '{"a":1}\n')
  return {root, fragments, output: path.join(root, 'generated/en/manifests/rest-derivation.json')}
}

test('builds the same fragment evidence schema for every REST locale', () => {
  const {fragments} = fixture()
  const toolingSha = 'a'.repeat(40)
  const generatedAt = '2026-09-09T00:00:00.000Z'
  const manifests = ['en', 'zh-CN', 'ja-JP'].map(locale => buildRestDerivationManifest({
    fragmentRoot: fragments, locale, toolingSha, generatedAt,
  }))
  assert.deepEqual(manifests.map(manifest => Object.keys(manifest)), Array(3).fill([
    'schemaVersion', 'locale', 'fragmentHashes', 'toolingSha', 'generatedAt',
  ]))
  assert.deepEqual(manifests[0].fragmentHashes, manifests[1].fragmentHashes)
  assert.deepEqual(manifests[1].fragmentHashes, manifests[2].fragmentHashes)
  assert.deepEqual(Object.keys(manifests[0].fragmentHashes), ['01.json', '02.json'])
})

test('writes and validates exact fragment hashes', () => {
  const {fragments, output} = fixture()
  writeRestDerivationManifest({
    fragmentRoot: fragments,
    locale: 'en',
    toolingSha: 'b'.repeat(40),
    generatedAt: '2026-09-09T00:00:00.000Z',
    outputPath: output,
  })
  assert.equal(validateRestDerivationManifest({fragmentRoot: fragments, manifestPath: output, locale: 'en'}).locale, 'en')
  fs.writeFileSync(path.join(fragments, '01.json'), '{"changed":true}\n')
  assert.throws(
    () => validateRestDerivationManifest({fragmentRoot: fragments, manifestPath: output, locale: 'en'}),
    /REST_DERIVATION_FRAGMENT_DRIFT/,
  )
})

test('fails closed on schema, locale, digest, and fragment-set errors', () => {
  const valid = {
    schemaVersion: 1,
    locale: 'ja-JP',
    fragmentHashes: {'01.json': 'c'.repeat(64)},
    toolingSha: 'd'.repeat(40),
    generatedAt: '2026-09-09T00:00:00.000Z',
  }
  assert.throws(() => parseRestDerivationManifest({...valid, extra: true}, 'ja-JP'), /KEYS_INVALID/)
  assert.throws(() => parseRestDerivationManifest(valid, 'en'), /LOCALE_MISMATCH/)
  assert.throws(() => parseRestDerivationManifest({...valid, fragmentHashes: {'../01.json': 'c'.repeat(64)}}, 'ja-JP'), /FRAGMENT_RECORD_INVALID/)
  const {fragments} = fixture()
  fs.writeFileSync(path.join(fragments, 'README.md'), 'not a fragment\n')
  assert.throws(() => buildRestDerivationManifest({
    fragmentRoot: fragments,
    locale: 'en',
    toolingSha: 'e'.repeat(40),
    generatedAt: '2026-09-09T00:00:00.000Z',
  }), /FRAGMENT_SET_INVALID/)
})

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const docPath = path.join(__dirname, 'CUSTOM_ATTRIBUTES.md');

function readDoc() {
  return fs.readFileSync(docPath, 'utf8');
}

test('documents all three lifecycle attributes', () => {
  const doc = readDoc();
  for (const attribute of ['x-added-at', 'x-last-modified', 'x-deprecated-since']) {
    assert.match(doc, new RegExp(`\`${attribute}\``));
  }
});

test('documents the minor-track format and managed scopes', () => {
  const doc = readDoc();
  assert.match(doc, /major\.minor\.x|`[0-9]+\.[0-9]+\.x`/i);
  assert.match(doc, /operation/i);
  assert.match(doc, /contract-element|property|parameter/i);
});

test('documents audit-only x-last-modified and retained deprecation', () => {
  const doc = readDoc();
  assert.match(doc, /x-last-modified.*(?:never|does not).*(?:visibility|visible)|x-last-modified.*audit/i);
  assert.match(doc, /x-last-modified/i);
  assert.match(doc, /deprecated.*retain|retain.*deprecated|remains present/i);
  assert.match(doc, /x-removed-since.*out of scope|does not introduce `?x-removed-since`?|not.*x-removed-since/i);
});

test('documents latest and track publication policies', () => {
  const doc = readDoc();
  assert.match(doc, /latest/i);
  assert.match(doc, /track/i);
  assert.match(doc, /zilliz/i);
  assert.match(doc, /milvus/i);
  assert.match(doc, /api-version|api surface/i);
  assert.match(doc, /release-track|release track/i);
});

test('documents staged enforcement from audit to required', () => {
  const doc = readDoc();
  assert.match(doc, /audit-compatible|audit compatible/i);
  assert.match(doc, /bootstrap/i);
  assert.match(doc, /post-bootstrap|hard validation|required/i);
});

const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')

const collectionSpecPath = path.join(__dirname, 'meta/openapi/05-collection-operations-v2.json')
const onDemandClusterSpecPath = path.join(__dirname, 'meta/openapi/33-on-demand-cluster-operations-v2.json')

function loadJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf-8'))
}

function testListCollectionsAuthorizationVariesByEndpointTab() {
  const spec = loadJson(collectionSpecPath)
  const params = spec.paths['/v2/vectordb/collections/list'].post.parameters || []

  const authParams = params.filter(p => p.name === 'Authorization')
  assert.equal(authParams.length, 2, 'List Collections should define two Authorization variants (cluster + on-demand)')

  const clusterAuth = authParams.find(p => Array.isArray(p['x-base-url-target']) && p['x-base-url-target'].includes('cluster'))
  const onDemandAuth = authParams.find(p => Array.isArray(p['x-base-url-target']) && p['x-base-url-target'].includes('on-demand-compute'))

  assert.ok(clusterAuth, 'Missing cluster Authorization variant')
  assert.ok(onDemandAuth, 'Missing on-demand Authorization variant')

  assert.match(clusterAuth.description || '', /username:password/, 'Cluster Authorization should allow username:password token')
  assert.equal(
    /username:password/.test(onDemandAuth.description || ''),
    false,
    'On-demand Authorization should not mention username:password',
  )

  assert.match(
    clusterAuth?.['x-i18n']?.['zh-CN']?.description || '',
    /username:password/,
    'Cluster Authorization zh-CN description should allow username:password token',
  )
  assert.equal(
    /username:password/.test(onDemandAuth?.['x-i18n']?.['zh-CN']?.description || ''),
    false,
    'On-demand Authorization zh-CN description should not mention username:password',
  )
}

function testCreateOnDemandClusterHasZhCnSuccessResponseExample() {
  const spec = loadJson(onDemandClusterSpecPath)
  const examples = spec.paths['/v2/clusters/createOnDemandCluster']
    .post.responses['200'].content['application/json'].examples

  const zhCnSuccess = Object.values(examples).find(ex => (
    ex?.['x-target-response'] === 'OPTION 1'
    && ex?.['x-target-lang'] === 'zh-CN'
    && ex?.value?.data?.clusterId
    && ex?.value?.data?.prompt
  ))

  assert.ok(zhCnSuccess, 'Create On-Demand Cluster should have zh-CN OPTION 1 success example')
}

function run() {
  testListCollectionsAuthorizationVariesByEndpointTab()
  testCreateOnDemandClusterHasZhCnSuccessResponseExample()
  console.log('apifox issues 10717 and 10802 regression tests passed')
}

run()

'use strict'

const assert = require('node:assert/strict')
const fs = require('node:fs')
const nunjucks = require('nunjucks')
const os = require('node:os')
const path = require('node:path')
const test = require('node:test')
const RefGen = require('./refGen')

test('synthetic REST version pages resolve their real, non-empty description', () => {
  const targetPath = fs.mkdtempSync(path.join(os.tmpdir(), 'rest-frontmatter-'))
  try {
    const generator = new RefGen({
      lang: 'en-US',
      target: 'zilliz',
      target_path: targetPath,
      specifications: {
        tags: [{ name: 'Collections (V2)' }],
        paths: {
          '/v2/collections': {
            get: {
              summary: 'List Collections',
              tags: ['Collections (V2)'],
              responses: { 200: { description: 'ok' } },
            },
          },
        },
      },
    })

    generator.make_groups()

    const versionPage = fs.readFileSync(path.join(targetPath, 'v2/v2.mdx'), 'utf8')
    assert.match(versionPage, /^description: "Zilliz Cloud RESTful API V2 documentation\.?"$/m)
    assert.doesNotMatch(versionPage, /^description: ""$/m)
    assert.doesNotMatch(versionPage, /^description: null$/m)
  } finally {
    fs.rmSync(targetPath, { recursive: true, force: true })
  }
})

test('REST group pages serialize a missing description lookup as an empty YAML string, not null', () => {
  const env = new nunjucks.Environment(
    new nunjucks.FileSystemLoader(path.join(__dirname, 'templates')),
    { autoescape: false },
  )
  const rendered = env.getTemplate('group.mdx').render({
    group_name: 'Untitled',
    position: 1,
    slug: 'untitled',
    beta_tag: 'FALSE',
    description: '',
    group_route: '/restful/untitled',
  })
  assert.match(rendered, /^description: ""$/m)
  assert.doesNotMatch(rendered, /^description: null$/m)
})

test('explicit control-plane generation preserves the established public REST slug', async () => {
  const targetPath = fs.mkdtempSync(path.join(os.tmpdir(), 'rest-control-plane-slug-'))
  try {
    const generator = new RefGen({
      lang: 'en-US', target: 'zilliz', target_path: targetPath, apiSurface: 'control-plane',
      specifications: {
        tags: [{name: 'Projects (V2)'}],
        paths: {'/v2/projects': {get: {summary: 'List Projects', tags: ['Projects (V2)'], responses: {200: {description: 'ok'}}}}},
      },
    })
    generator.make_groups()
    await generator.write_refs()
    const page = fs.readFileSync(path.join(targetPath, 'v2/control-plane/projects-v2/list-projects-v2.mdx'), 'utf8')
    assert.match(page, /^slug: \/restful\/list-projects-v2$/m)
    assert.doesNotMatch(page, /\/restful\/control-plane\//)
  } finally {
    fs.rmSync(targetPath, {recursive: true, force: true})
  }
})

