const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {publishIntegratedSpecs} = require('./integratedSpecPublisher');

const fixturePath = name => path.join(__dirname, 'test-fixtures/integrated-spec', name);

function tempDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'integrated-spec-publisher-'));
}

class RecordingUploader {
  constructor() {
    this.uploads = [];
  }

  async uploadArtifact(artifact) {
    this.uploads.push(artifact);
    return `https://example.com/${artifact.filename}`;
  }
}

test('publishes latest local artifacts and uploads identical prepared bytes', async () => {
  const dir = tempDir();
  const uploader = new RecordingUploader();
  const result = await publishIntegratedSpecs({
    specifications: fixturePath('canonical.json'),
    publicationPolicy: 'latest',
    target: 'zilliz',
    apiSurface: 'data-plane',
    protocolVersion: 'v2',
    language: 'en-US',
    outputDirectory: dir,
    uploader,
  });

  const local = fs.readFileSync(path.join(dir, 'openapi-zilliz-data-plane-v2-en-US.json'));
  const uploaded = uploader.uploads.find(entry => entry.filename === 'openapi-zilliz-data-plane-v2-en-US.json');
  assert.ok(uploaded);
  assert.deepEqual(Buffer.from(uploaded.bytes), local);
  assert.equal(uploaded.sha256, result.localArtifacts.find(entry => entry.filename === 'openapi-zilliz-data-plane-v2-en-US.json').sha256);
  assert.ok(result.manifest);
  fs.rmSync(dir, {recursive: true, force: true});
});

test('publishes track artifacts without an api surface', async () => {
  const dir = tempDir();
  const uploader = new RecordingUploader();
  const result = await publishIntegratedSpecs({
    specifications: fixturePath('milvus-2.6.x.json'),
    publicationPolicy: 'track',
    target: 'milvus',
    releaseTrack: '2.6.x',
    apiSurface: 'data-plane',
    language: 'zh-CN',
    outputDirectory: dir,
    uploader,
  });

  assert.equal(fs.existsSync(path.join(dir, 'openapi-milvus-data-plane-2.6.x-zh-CN.json')), true);
  assert.equal(result.manifest.releaseTrack, '2.6.x');
  assert.equal(result.manifest.apiSurface, 'data-plane');
  fs.rmSync(dir, {recursive: true, force: true});
});

test('compatibility aliases are rejected because the integrated interface is unlaunched', async () => {
  const dir = tempDir();
  const uploader = new RecordingUploader();
  await assert.rejects(() => publishIntegratedSpecs({
    specifications: fixturePath('canonical.json'),
    publicationPolicy: 'latest',
    target: 'zilliz',
    apiSurface: 'data-plane',
    protocolVersion: 'v2',
    language: 'en-US',
    outputDirectory: dir,
    uploader,
    enableCompatibilityAliases: true,
  }), /REST_COMPATIBILITY_ALIASES_UNSUPPORTED/);
  fs.rmSync(dir, {recursive: true, force: true});
});

test('upload failure leaves local artifacts intact', async () => {
  const dir = tempDir();
  const uploader = {
    async uploadArtifact() {
      throw new Error('upload failed');
    },
  };

  await assert.rejects(
    () => publishIntegratedSpecs({
      specifications: fixturePath('canonical.json'),
      publicationPolicy: 'latest',
      target: 'zilliz',
      apiSurface: 'data-plane',
      protocolVersion: 'v2',
      language: 'en-US',
      outputDirectory: dir,
      uploader,
    }),
    /upload failed/,
  );

  assert.equal(fs.existsSync(path.join(dir, 'openapi-zilliz-data-plane-v2-en-US.json')), true);
  assert.equal(fs.existsSync(path.join(dir, 'manifest.json')), true);
  fs.rmSync(dir, {recursive: true, force: true});
});

const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');

function sortObjectKeys(value) {
  if (Array.isArray(value)) return value.map(sortObjectKeys);
  if (!value || typeof value !== 'object') return value;
  const sorted = {};
  for (const key of Object.keys(value).sort()) {
    sorted[key] = sortObjectKeys(value[key]);
  }
  return sorted;
}

function deterministicStringify(value) {
  return `${JSON.stringify(sortObjectKeys(value), null, 2)}\n`;
}

function sha256(bytes) {
  return crypto.createHash('sha256').update(bytes).digest('hex');
}

function integratedSpecFilename(options) {
  if (options.publicationPolicy === 'latest') {
    if (!options.target || !options.apiSurface || !options.language) {
      throw new Error('REST_ARTIFACT_FILENAME_INVALID: latest artifacts require target, apiSurface, and language');
    }
    if (options.apiSurface === 'control-plane') return `openapi-${options.target}-control-plane-${options.language}.json`;
    if (!options.protocolVersion) throw new Error('REST_ARTIFACT_FILENAME_INVALID: data-plane latest requires protocolVersion');
    return `openapi-${options.target}-data-plane-${options.protocolVersion}-${options.language}.json`;
  }

  if (options.publicationPolicy === 'track') {
    if (!options.target || !options.releaseTrack || !options.language) {
      throw new Error('REST_ARTIFACT_FILENAME_INVALID: track artifacts require target, releaseTrack, and language');
    }
    if (options.apiSurface !== 'data-plane') throw new Error('REST_ARTIFACT_FILENAME_INVALID: track artifacts require data-plane');
    return `openapi-${options.target}-data-plane-${options.releaseTrack}-${options.language}.json`;
  }

  throw new Error(`REST_ARTIFACT_FILENAME_INVALID: unsupported publication policy "${options.publicationPolicy}"`);
}

function createArtifact(filename, bytes) {
  return {
    filename,
    bytes,
    length: bytes.length,
    sha256: sha256(bytes),
    contentType: 'application/json',
  };
}

function buildManifest(buildResult, metadata, files) {
  const semanticManifest = {
    schemaVersion: '1.0',
    target: metadata.target,
    publicationPolicy: metadata.publicationPolicy,
    releaseTrack: metadata.releaseTrack ?? null,
    apiSurface: metadata.apiSurface,
    protocolVersion: metadata.protocolVersion ?? null,
    language: metadata.language,
    source: {
      identity: metadata.sourceIdentity || null,
      digest: metadata.sourceDigest || null,
    },
    generator: {
      gitSha: metadata.generatorGitSha || null,
    },
    collection: metadata.collection || null,
    review: metadata.review || null,
    files: files.map(({filename, length, sha256: digest}) => ({filename, length, sha256: digest})),
    operations: buildResult.endpointInventory || [],
    stats: buildResult.stats || {},
    validation: {
      danglingLocalRefs: 'none',
    },
  };

  const semanticDigest = sha256(Buffer.from(deterministicStringify(semanticManifest), 'utf8'));
  return {...semanticManifest, semanticDigest};
}

function prepareIntegratedArtifact(buildResult, metadata, extraArtifacts = []) {
  const filename = integratedSpecFilename(metadata);
  const bytes = Buffer.from(deterministicStringify(buildResult.spec), 'utf8');
  const specArtifact = createArtifact(filename, bytes);
  const manifest = buildManifest(buildResult, metadata, [specArtifact, ...extraArtifacts]);
  const manifestArtifact = createArtifact('manifest.json', Buffer.from(deterministicStringify(manifest), 'utf8'));

  return {
    artifacts: [specArtifact, ...extraArtifacts, manifestArtifact],
    manifest,
    semanticDigest: manifest.semanticDigest,
  };
}

function writeIntegratedArtifacts(outputDirectory, artifacts) {
  fs.mkdirSync(outputDirectory, {recursive: true});
  const tempFiles = [];

  try {
    for (const artifact of artifacts) {
      const tempPath = path.join(outputDirectory, `.${artifact.filename}.${process.pid}.${tempFiles.length}.tmp`);
      fs.writeFileSync(tempPath, artifact.bytes);
      tempFiles.push({tempPath, finalPath: path.join(outputDirectory, artifact.filename)});
    }

    for (const {tempPath, finalPath} of tempFiles) {
      fs.renameSync(tempPath, finalPath);
    }
  } catch (err) {
    for (const {tempPath} of tempFiles) {
      try {
        if (fs.existsSync(tempPath)) fs.rmSync(tempPath);
      } catch {
        // Best-effort cleanup while preserving the original error.
      }
    }
    throw err;
  }

  return artifacts.map(artifact => ({
    ...artifact,
    path: path.join(outputDirectory, artifact.filename),
  }));
}

module.exports = {
  integratedSpecFilename,
  prepareIntegratedArtifact,
  writeIntegratedArtifacts,
  deterministicStringify,
  sha256,
};

'use strict'

const test = require('node:test')
const assert = require('node:assert/strict')
const fs = require('node:fs')
const os = require('node:os')
const path = require('node:path')
const {createRestCompletenessReceipt, validateRestCompletenessReceipt, validateRestDeletionEvidence} = require('./restCompletenessReceipt')
const {sha256Digest} = require('./fragmentCollection')

const SHA_A = 'a'.repeat(40)
const SHA_B = 'b'.repeat(40)

function fragment(service, endpoint, operationId) {
  return {
    openapi: '3.0.3',
    info: {title: 'REST', version: 'v2'},
    'x-zdoc-fragment': {schemaVersion: '1.0', apiSurface: 'control-plane', service},
    tags: [{name: service}],
    paths: {[endpoint]: {get: {operationId, tags: [service], responses: {200: {$ref: '#/components/responses/Shared'}}}}},
    components: {responses: {Shared: {description: 'shared'}}},
  }
}

function writeCollection(services) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'rest-completeness-collection-'))
  const entries = services.map(service => {
    const filename = `${service.id}.openapi.json`
    const bytes = Buffer.from(`${JSON.stringify(service.spec, null, 2)}\n`)
    fs.writeFileSync(path.join(root, filename), bytes)
    return {id: service.id, fragment: filename, sha256: sha256Digest(bytes), operationCount: 1}
  })
  const manifest = {
    schemaVersion: '1.0', collectionId: 'control-plane-completeness', apiSurface: 'control-plane',
    source: {repository: 'zilliz-cloud', revision: SHA_A},
    generator: {repository: 'feishu-markdown-bridge', revision: SHA_B, configDigest: `sha256:${'1'.repeat(64)}`},
    review: {manifestDigest: `sha256:${'1'.repeat(64)}`, approvalDigest: `sha256:${'2'.repeat(64)}`},
    services: entries,
  }
  fs.writeFileSync(path.join(root, 'collection-manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`)
  return root
}

function inventoryEntry(root, relative, content) {
  const target = path.join(root, relative)
  fs.mkdirSync(path.dirname(target), {recursive: true})
  fs.writeFileSync(target, content)
  return {path: relative, sha256: sha256Digest(Buffer.from(content))}
}

test('creates and validates a complete REST generation receipt from a fragment collection', () => {
  const collection = writeCollection([
    {id: 'projects', spec: fragment('projects', '/v2/projects', 'listProjects')},
    {id: 'usage', spec: fragment('usage', '/v2/usage', 'getUsage')},
  ])
  const generatedRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'rest-completeness-generated-'))
  const output = [
    inventoryEntry(generatedRoot, 'content/en/reference/api/restful/restful/v2/projects.mdx', '# Projects\n'),
    inventoryEntry(generatedRoot, 'content/en/reference/api/restful/restful/v2/usage.mdx', '# Usage\n'),
  ]
  const receipt = createRestCompletenessReceipt({
    collectionDirectory: collection,
    sourceBaselineSha: SHA_A,
    sourceCheckpointSha: SHA_B,
    outputInventory: output,
  })
  assert.equal(validateRestCompletenessReceipt(receipt), receipt)
  assert.equal(receipt.inputInventory.length, 2)
  assert.equal(receipt.outputInventory.length, 2)
  fs.rmSync(collection, {recursive: true, force: true})
  fs.rmSync(generatedRoot, {recursive: true, force: true})
})

test('rest deletion evidence requires baseline presence and complete checkpoint absence', () => {
  const collection = writeCollection([
    {id: 'projects', spec: fragment('projects', '/v2/projects', 'listProjects')},
  ])
  const generatedRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'rest-completeness-deletion-'))
  const output = [inventoryEntry(generatedRoot, 'content/en/reference/api/restful/restful/v2/projects.mdx', '# Projects\n')]
  const receipt = createRestCompletenessReceipt({
    collectionDirectory: collection,
    sourceBaselineSha: SHA_A,
    sourceCheckpointSha: SHA_B,
    outputInventory: output,
  })
  const deletedPath = 'content/en/reference/api/restful/restful/v2/old.mdx'
  assert.equal(validateRestDeletionEvidence({receipt, sourcePath: deletedPath}), receipt)
  assert.throws(() => validateRestDeletionEvidence({receipt, sourcePath: deletedPath, sourceMissingAtCheckpoint: false}), /absent.*complete checkpoint/)
  assert.throws(() => validateRestDeletionEvidence({receipt, sourcePath: output[0].path}), /present.*complete output inventory/)
  fs.rmSync(collection, {recursive: true, force: true})
  fs.rmSync(generatedRoot, {recursive: true, force: true})
})

const assert = require('node:assert/strict')
const fs = require('node:fs')
const os = require('node:os')
const path = require('node:path')
const { spawnSync } = require('node:child_process')
const RefGen = require('./refGen')

function listFiles(dir) {
  return fs.readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter(entry => entry.isFile())
    .map(entry => path.join(entry.parentPath ?? entry.path, entry.name))
}

function buildSpecifications() {
  return {
    tags: [
      { name: 'Vector (V1)' },
      { name: 'Collection (V1)' },
      { name: 'Vector Operations (V2)' },
    ],
    paths: {
      '/v1/vector/collections': {
        get: { summary: 'List', tags: ['Vector (V1)'], responses: {} },
      },
      '/v1/collections': {
        get: { summary: 'List', tags: ['Collection (V1)'], responses: {} },
      },
      '/v2/vectordb/collections/list': {
        post: { summary: 'List', tags: ['Vector Operations (V2)'], responses: {} },
      },
    },
  }
}

function buildGenerator(target, targetPath) {
  return new RefGen({
    specifications: buildSpecifications(),
    lang: 'en-US',
    target,
    target_path: targetPath,
  })
}

async function main() {
  // milvus.io namespaces pages by version and group folder and its slug
  // convention drops the -v2 suffix, so same-verb pages across versions and
  // groups are expected. The uniqueness check must key on the physical page
  // path there, where a repeated key would overwrite an actual file.
  const milvusTarget = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'refgen-route-milvus-')), 'out')
  const milvus = buildGenerator('milvus', milvusTarget)
  milvus.make_groups()
  await milvus.write_refs()
  const milvusListPages = listFiles(milvusTarget).filter(file => path.basename(file) === 'list.mdx')
  assert.equal(milvusListPages.length, 3)
  assert.equal(new Set(milvusListPages.map(file => path.dirname(file))).size, 3)

  // zdoc sites publish a flat /restful/<slug> route space, where a repeated
  // slug really is a collision and must keep failing closed.
  const zillizTarget = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'refgen-route-zilliz-')), 'out')
  const zilliz = buildGenerator('zilliz', zillizTarget)
  zilliz.make_groups()
  await assert.rejects(zilliz.write_refs(), /REST_PAGE_ROUTE_CONFLICT: \/restful\/list/)

  // The production CLI must fail closed on the same conflict: the rejection
  // has to surface before the derivation manifest is written (and before the
  // S3 upload that follows it), so a failed run leaves no side effects
  // beyond the target tree it was asked to generate into.
  const cliDir = fs.mkdtempSync(path.join(os.tmpdir(), 'refgen-route-cli-'))
  const fragmentDir = path.join(cliDir, 'fragments')
  fs.mkdirSync(fragmentDir)
  fs.writeFileSync(path.join(fragmentDir, 'spec.json'), `${JSON.stringify(buildSpecifications())}\n`)
  const manifestPath = path.join(cliDir, 'rest-derivation.json')
  // The standalone entry registers the fetch options directly on the
  // program, so no subcommand word is passed here. This also keeps the test
  // compatible with commander >= 13, which errors on excess positionals
  // where commander 10 silently ignored them.
  const cli = spawnSync(process.execPath, [
    path.join(__dirname, 'index.js'),
    '-s', fragmentDir,
    '-l', 'en-US',
    '-o', path.join(cliDir, 'out'),
    '-t', 'zilliz',
    '--derivation-manifest', manifestPath,
    '--tooling-sha', 'a'.repeat(40),
    '--generated-at', '2026-01-01T00:00:00.000Z',
  ], { encoding: 'utf8' })
  assert.notEqual(cli.status, 0)
  assert.match(cli.stderr, /REST_PAGE_ROUTE_CONFLICT: \/restful\/list/)
  assert.equal(fs.existsSync(manifestPath), false, 'derivation manifest must not be written on a route conflict')
}

main().then(
  () => process.exit(0),
  (err) => {
    console.error(err)
    process.exit(1)
  }
)

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const crypto = require('node:crypto');
const {spawnSync} = require('node:child_process');

const cliPath = path.join(__dirname, 'index.js');
const fixture = name => path.join(__dirname, 'test-fixtures/integrated-spec', name);

function run(args) {
  return spawnSync(process.execPath, [cliPath, ...args], {encoding: 'utf8'});
}

function tempDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'integrated-spec-cli-'));
}

function collection(specPath, apiSurface, releaseTrack) {
  const dir = tempDir();
  const serviceId = apiSurface === 'control-plane' ? 'projects' : 'milvus-rest';
  const spec = JSON.parse(fs.readFileSync(specPath, 'utf8'));
  spec['x-zdoc-fragment'] = {schemaVersion: '1.0', apiSurface, service: serviceId};
  const filename = `${serviceId}.openapi.json`;
  const bytes = Buffer.from(`${JSON.stringify(spec, null, 2)}\n`);
  fs.writeFileSync(path.join(dir, filename), bytes);
  const digest = value => `sha256:${crypto.createHash('sha256').update(value).digest('hex')}`;
  const httpMethods = new Set(['get', 'put', 'post', 'delete', 'patch', 'options', 'head', 'trace']);
  const operationCount = Object.values(spec.paths || {}).reduce(
    (count, pathItem) => count + Object.keys(pathItem || {}).filter(method => httpMethods.has(method.toLowerCase())).length,
    0,
  );
  const manifest = {
    schemaVersion: '1.0', collectionId: `${apiSurface}-fixture`, apiSurface,
    ...(releaseTrack ? {releaseTrack} : {}),
    source: {repository: apiSurface === 'control-plane' ? 'zilliz-cloud' : 'milvus', revision: 'a'.repeat(40)},
    generator: {repository: 'feishu-markdown-bridge', revision: 'b'.repeat(40), configDigest: `sha256:${'1'.repeat(64)}`},
    review: {manifestDigest: `sha256:${'2'.repeat(64)}`, approvalDigest: `sha256:${'3'.repeat(64)}`},
    services: [{id: serviceId, fragment: filename, sha256: digest(bytes), operationCount}],
  };
  fs.writeFileSync(path.join(dir, 'collection-manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`);
  return dir;
}

